import{_ as o,o as t,c as i,a3 as n}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"Disable icon styling patching","description":"Learn how to disable icon styling patching and when to use this performance option","frontmatter":{"title":"Disable icon styling patching","description":"Learn how to disable icon styling patching and when to use this performance option"},"headers":[],"relativePath":"en/projects/uix/extras/disable-icon-styling.md","filePath":"en/projects/uix/extras/disable-icon-styling.md","lastUpdated":1793447386000}'),a={name:"en/projects/uix/extras/disable-icon-styling.md"};function r(s,e,c,l,d,h){return t(),i("div",null,[...e[0]||(e[0]=[n('<blockquote><p>Adapted from the canonical English UIX documentation by <a href="https://github.com/Lint-Free-Technology/uix" target="_blank" rel="noreferrer">Lint-Free-Technology/uix</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>. Source: <code>dev</code> / <strong>9.0.0-beta.6</strong>, revision <a href="https://github.com/Lint-Free-Technology/uix/commit/e6fb84dd715ea4bac9a330357705897ea8d44690" target="_blank" rel="noreferrer">e6fb84d</a>, reviewed 31 October 2026. This source mirror may describe preview behavior beyond stable 8.4.0. Markup adapted for this site; the <a href="https://uix.lf.technology/" target="_blank" rel="noreferrer">original documentation</a> remains authoritative.</p></blockquote><h1 id="disable-icon-styling-patching" tabindex="-1">Disable icon styling patching <a class="header-anchor" href="#disable-icon-styling-patching" aria-label="Permalink to &quot;Disable icon styling patching&quot;">​</a></h1><p>By default, UIX patches standard Home Assistant icon elements (<code>ha-icon</code>, <code>ha-state-icon</code>, <code>ha-svg-icon</code>) to allow custom styling and overrides (such as <code>--uix-icon</code>, <code>--uix-icon-color</code>, <code>--uix-icon-dim</code>, or <code>--uix-icon-for-&lt;entity_id&gt;</code>). UIX provides an option to disable this icon patching behavior to improve rendering performance and reduce CPU overhead on low-power devices.</p><h2 id="setting-via-the-integration-ui" tabindex="-1">Setting via the integration UI <a class="header-anchor" href="#setting-via-the-integration-ui" aria-label="Permalink to &quot;Setting via the integration UI&quot;">​</a></h2><p>The option is <strong>unset by default</strong>. To set the option:</p><ol><li>In Home Assistant, go to <strong>Settings → Devices &amp; Services → UI eXtension → Configure</strong>.</li><li>Select <strong>Performance settings</strong> from the menu.</li><li>Toggle <strong>Disable icon styling patching</strong> on.</li><li>Save.</li></ol><p>The setting takes effect immediately across all connected browser sessions — no page reload required.</p><h2 id="behavior-when-set" tabindex="-1">Behavior when set <a class="header-anchor" href="#behavior-when-set" aria-label="Permalink to &quot;Behavior when set&quot;">​</a></h2><p>When this option is set:</p><ul><li>Standard Home Assistant icon elements are <strong>not patched</strong> or monitored for custom icon properties.</li><li>Existing custom icon or icon color overrides via CSS variables (e.g. <code>--uix-icon</code>, <code>--uix-icon-color</code>, <code>--uix-icon-dim</code>, <code>--uix-icon-for-*</code>) will <strong>not</strong> be applied to standard icon elements.</li></ul>',10)])])}const u=o(a,[["render",r]]);export{p as __pageData,u as default};
